css:
.p13-page { display: grid; grid-template-rows: auto 1fr; min-height: 100cqh; overflow-x: clip; }
.p13-page > .deck, .p13-page > .p13-center { grid-row: 2; align-self: center; }
.p13-top { display: grid; gap: var(--s-2); width: 100%; max-width: 56rem; margin-inline: auto; padding: var(--s-3) var(--s-3) 0; grid-row: 1; }
.p13-top:empty { display: none; }
.p13-strip { --p13-strip-h: 9.5rem; }
.p13-strip .deck { --card: max(var(--card-min), min(var(--card-max), calc(100cqw - 2rem), calc(100cqh - 2rem - var(--peek) - var(--s-3) - var(--controls-h) - var(--p13-strip-h)))); }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p13-strip { --p13-strip-h: 19.5rem; } }
@media (max-width: 21.25rem) { .p13-strip { --p13-strip-h: 29.5rem; } }
.p13-scrolled .p13-page { margin-top: calc(var(--p13-shift, 5.25rem) * -1); }
.p13-e { --frame-w: var(--w2); }
.p13-focus { border-color: var(--blue); outline: var(--w1) solid var(--blue); outline-offset: calc(var(--w1) * -2); }
.p13-w { position: relative; display: inline-grid; }
.p13-tipw { position: relative; display: inline-flex; }
.p13-tip-up { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); left: 50%; translate: -50% 0; width: max-content; max-width: min(17.5rem, 80vw); text-align: center; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p13-tip-up.p13-tip-start { left: 0; translate: 0 0; text-align: start; }
  .p13-tip-up.p13-tip-end { left: auto; right: 0; translate: 0 0; text-align: end; }
}
.p13-tip-dn { position: absolute; z-index: 30; top: calc(100% + var(--s-1)); right: 0; width: max-content; max-width: min(17.5rem, 80vw); }
.btn .spinner, .banner .spinner { width: var(--icon-sm); height: var(--icon-sm); }

.deck-card__foot.p-solo > :first-child { justify-self: center; }

.p13-scroll { padding-block: var(--s-1); border-block: var(--w1) solid var(--rule); }
.p13-prog { margin: 0; }
.p13-addrow { display: grid; gap: var(--s-1); justify-items: start; }
.p13-m .rec__title { display: flex; align-items: center; gap: var(--s-1); }
.deck-card .rec.p13-m { grid-template-columns: auto minmax(0, 1fr) auto; grid-template-areas: "lead title value" "lead sub value" "actions actions actions"; row-gap: 0; }
.deck-card .rec.p13-m .rec__value { align-self: start; }
.deck-card .rec.p13-m .rec__actions { flex-wrap: wrap; justify-content: flex-end; }
@container card (max-width: 24rem) {
  .deck-card .rec.p13-m { grid-template-columns: auto minmax(0, 1fr); grid-template-areas: "lead title" "lead sub" "lead value" "actions actions"; }
}
.p13-m.p13-gray .rec__title, .p13-m.p13-gray .rec__value, .p13-m.p13-gray .rec__sub { color: var(--c-disabled-text); }
.p13-m.p13-gray .rec__sub { font-size: var(--fs-cap); }
.p13-over { display: block; font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); font-weight: var(--fw-regular); }
.p13-hist { display: grid; gap: var(--s-2); margin-top: var(--s-2); }
.p13-quick { display: grid; gap: var(--s-2); padding: var(--s-2) var(--s-3); margin: calc(var(--s-1) * -1) 0 0; }
.p13-quick__f { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-2); align-items: start; }
.p13-quick__b { display: flex; gap: var(--s-2); }
.p13-quick__b > * { flex: 1 1 0; }
.p13-expl { margin: calc(var(--s-1) * -1) 0 0; padding: 0 var(--s-3) var(--s-1) calc(var(--s-3) + var(--hit)); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); }
.p13-mode { display: grid; gap: var(--s-1); border: 0; margin: 0; padding: 0; min-width: 0; }
.p13-mode legend { padding: 0; font-weight: var(--fw-bold); font-size: var(--fs-small); }
.p13-modeline { font-size: var(--fs-small); line-height: var(--lh-small); font-weight: var(--fw-semibold); color: var(--muted); }
.p13-fcenter { align-items: center; justify-content: center; text-align: center; }
.p13-cs { display: grid; justify-items: center; gap: var(--s-3); }
.p13-cs .banner { text-align: start; }
.p13-menu .menu { width: max-content; min-width: 8.75rem; max-width: calc(var(--card) - 1rem); z-index: 20; }
.p13-menu .menu__item { justify-content: flex-start; }
.p13-menu.menu-pop .menu { right: 0; }
.deck-card__head .menu-pop { flex: none; }
.p13-undo { display: block; }
.p13-dlg .dialog__body p { max-width: var(--measure); }
.p13-dlg .p13-word { margin-top: var(--s-1); }
.p13-dlg .p13-two { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--s-2); }
.p13-dlg .btn .ico { margin: 0; }
.p13-tipw { position: relative; display: inline-flex; }
.p13-lnk { display: inline-grid; place-items: center; color: var(--muted); }
.p13-hovr { border-color: var(--ink); }
.p13-sh { margin-top: calc(var(--p13-sn) * -1); }
@media (min-width: 48rem) and (min-height: 31.25rem) { .p13-sh { margin-top: calc(var(--p13-sw) * -1); } }

.p15-dlg .dialog__body { gap: var(--s-3); }
.p15-dlg .dialog__body p { max-width: var(--measure); }
.p15-fh { justify-content: flex-start; flex-wrap: wrap; column-gap: var(--s-2); }
.p15-fo { outline: var(--focus-ring); outline-offset: var(--focus-offset); }
.p15-selfo { border: var(--w2) solid var(--blue); }
.p15-ph { color: var(--muted); }
.p15-list { max-height: 12rem; overflow: auto; min-width: 0; display: flex; flex-direction: column; }
.p15-list > * { flex: none; }
.p15-list .menu__item { align-items: flex-start; flex-direction: column; gap: 0; justify-content: center; min-height: var(--row-h); padding-block: var(--s-1); }
.p15-list .menu__item > .row { width: 100%; justify-content: space-between; }
.p15-list .menu__item.p15-sub { padding-inline-start: var(--s-5); }
.p15-sub-t { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); font-weight: var(--fw-regular); }
.p15-list .menu__item[aria-selected="true"] .p15-sub-t { color: var(--blue); }
.p15-done { color: var(--muted); }
.p15-group { padding: var(--s-1) var(--s-3) 0; font-size: var(--fs-cap); line-height: var(--lh-cap); font-weight: var(--fw-bold); color: var(--muted); }
.p15-warn { padding: var(--s-1) var(--s-2); }
.p15-note { margin: 0; padding: 0 var(--s-4) var(--s-4); font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); max-width: var(--measure); }
.p15-dlg .dialog__foot { padding-bottom: var(--s-2); }
.p15-tipw { position: relative; display: flex; flex: 1 1 0; }
.p15-tipw > .btn { flex: 1; }
.p15-tip-up { position: absolute; z-index: 30; bottom: calc(100% + var(--s-1)); left: 50%; translate: -50% 0; width: max-content; max-width: min(17.5rem, 80vw); text-align: center; }
@media not all and (min-width: 48rem) and (min-height: 31.25rem) { .p15-tip-up.p15-tip-end { left: auto; right: 0; translate: 0 0; text-align: end; } }
.p15-dlg .btn .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p15-load { display: flex; align-items: center; gap: var(--s-2); }
.p15-load .spinner { width: var(--icon-sm); height: var(--icon-sm); }
.p15-e { --frame-w: var(--w2); }
.p15-sh { margin-top: calc(var(--sh-n) * -1); }

@media (max-width: 21.25rem) {
  .composer { gap: var(--s-1); padding-inline: var(--s-1); }
  .composer .input { padding-inline: var(--s-1); }
  .composer .input::placeholder { font-size: var(--fs-small); }
}

.p15-dlg .dialog__foot:has(.p15-tipw) { display: grid; grid-template-columns: 1fr 1fr; }
.p15-tipw { display: contents; }
.p15-tipw > .tip { position: static; translate: none; width: auto; max-width: none; grid-column: 1 / -1; grid-row: 2; text-align: start; }

.p15-done-w { font-size: var(--fs-cap); line-height: var(--lh-cap); color: var(--muted); font-weight: var(--fw-regular); }

@media not all and (min-width: 48rem) and (min-height: 31.25rem) {
  .p15-dlg .dialog__head { flex-wrap: wrap; }
  .p15-dlg .dialog__head > .ibtn { order: -1; margin-inline-start: auto; }
  .p15-dlg .dialog__title { flex: 1 1 100%; }
}
@media (max-width: 21.25rem) { .scrim { padding: var(--s-3); } }

.p13-m .rec__value .pg { margin: var(--s-1) 0 var(--s-1) auto; }
@container card (max-width: 24rem) { .deck-card .rec.p13-m .rec__value .pg { margin-left: 0; } }
.p13-progbar { display: grid; gap: var(--s-1); }
.p13-progbar .pg { margin-bottom: var(--s-1); }
.p13-mode .check { align-items: center; }
